const input=$json.body??$json;
const response=input.seller_response??input.response??{};
const text=String(response.text||input.response_text||"").trim();
const lower=text.toLowerCase();
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const amountMatch=text.replace(/[$,]/g,"").match(/(?:^|\\s)(\\d{2,7}(?:\\.\\d{1,2})?)(?:\\s|$)/);
const counteroffer=amountMatch?Number(amountMatch[1]):Number(input.counteroffer_amount);
const accepted=/\\b(yes|accept|accepted|deal|agreed|sounds good|let's do it|okay|ok)\\b/.test(lower);
const rejected=/\\b(no|reject|rejected|pass|not interested|decline|declined)\\b/.test(lower);
const question=/\\?|\\b(why|how|what|when|where|can you|could you|explain)\\b/.test(lower);
const counter=Number.isFinite(counteroffer)&&!accepted&&!rejected;
const noResponse=!text&&Boolean(input.no_response);
let classification=counter?"counteroffer":accepted?"accepted":rejected?"rejected":question?"question":noResponse?"no_response":text?"other_response":"unknown";
let nextWorkflow="WF-292",humanReview=false,reason="seller response classified";
if(blockers.length){nextWorkflow="WF-126";humanReview=true;reason="active blockers present";}
else if(classification==="counteroffer"){nextWorkflow="WF-292";humanReview=true;reason="counteroffer requires negotiation evaluation";}
else if(classification==="rejected"){nextWorkflow="WF-293";humanReview=true;reason="seller rejected offer; route to re-engagement/walk-away logic";}
else if(classification==="accepted"){nextWorkflow="WF-292";humanReview=true;reason="seller acceptance requires contract/negotiation gate";}
else if(classification==="no_response"){nextWorkflow="WF-290";reason="no response; maintain response/timeout state";}
const classificationResult={classification,response_text_present:Boolean(text),counteroffer_amount:Number.isFinite(counteroffer)?counteroffer:null,accepted,rejected,question,no_response:classification==="no_response",confidence:classification==="unknown"?"low":"high"};
return [{json:{...input,workflow:"WF-291",workflow_name:"Seller Response → Offer / Counteroffer Classification & Negotiation Routing Controller",status:"response_classified",seller_response_classification:classificationResult,next_workflow:nextWorkflow,human_review_required:humanReview,routing_reason:reason,audit:{event_type:"seller_response_classification_negotiation_routing",idempotency_key:input.idempotency_key||`wf-291:${input.deal_id||"unknown"}:${input.dispatch_id||"none"}:${input.version||1}`}}}];
